import {DATA,programFor,coursesFor,creditsOf,label} from './planner.js';
import {minorSummary} from './minor-summary.js';
import {planIssues} from './guidance.js';
import {questionnaireCard,questionNavigation} from './question-cards.js';
import {selectedMinor} from './minors.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const short=(s,n=130)=>{s=String(s||'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n-1).replace(/\s+\S*$/,'')+'…':s;};
const button=(action,text,primary=false,extra='')=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${action}" ${extra}>${text}</button>`;
const tabs=[['overview','Your space','◈'],['direction','Direction','↗'],['courses','Courses','▤'],['opportunities','Opportunities','◎'],['semesters','Semesters','▦']];
export function dashboardReady(j,plan){return {direction:!!(plan||j.programChosen&&j.advice?.kind==='recommend'),courses:!!(plan||j.details?.choices),opportunities:!!(plan?.targets?.internships?.length||plan?.targets?.exchanges?.length||j.details?.internships?.length||j.details?.exchanges?.length),semesters:!!plan};}
export function dashboardView(state,runtime={},account=null){
 const j=state.journey,plan=state.phase==='draft'?state.draftPlan:state.plan,profile=plan?.profile||j.profile,degree=programFor(profile),ready=dashboardReady(j,plan),panel=runtime.dashboardPanel||'overview',begun=!!(j.studentContext||j.advice||plan),name=account?.firstName||'',draft=state.phase==='draft';
 if(!begun||runtime.dashboardWelcome&&!ready.direction)return `<section class="launch-space"><span class="dashboard-kicker">YOUR NEXT CHAPTER</span><h1>${name?`Hi ${esc(name)}.<br>`:''}Let’s find your path.</h1><p>A few taps. A plan that feels like you.</p><div class="launch-path" aria-hidden="true"><span>✦</span><i></i><span>↗</span><i></i><span>◎</span><i></i><span>▦</span></div>${button('dashboard-start','Let’s go →',true)}<span class="launch-note">For students starting their first semester at AUI.</span></section>`;
 if(state.phase==='journey'&&!ready.direction&&j.advice?.kind==='clarify')return `<section class="discovery-space"><span class="dashboard-kicker">ONE QUICK FOLLOW-UP</span><form id="dashboard-clarification-form" class="discovery-card"><h2>${esc(short(j.advice.questions?.[0]||j.advice.summary,200))}</h2><label class="field">Your answer<textarea name="answer" rows="3" maxlength="2500" required ${runtime.busy?'disabled':''}></textarea></label><button class="button primary" type="submit" ${runtime.busy?'disabled':''}>Find my direction →</button></form><div class="deck-actions">${button('dashboard-direction-options','Choose my degree myself')}</div>${working(runtime)}${failure(runtime)}</section>`;
 if(state.phase==='journey'&&!ready.direction)return `<section class="discovery-space"><div class="discovery-top"><button class="text-button" data-action="dashboard-home">← Your space</button><span class="dashboard-kicker">FIND YOUR SPARK</span></div><fieldset class="discovery-card" ${runtime.busy?'disabled':''}>${questionnaireCard(j,runtime.validation)}</fieldset><div class="discovery-actions">${runtime.busy?'':questionNavigation(j)}</div>${working(runtime)}${failure(runtime)}</section>`;
 const completed=Object.values(ready).filter(Boolean).length,done=plan?plan.courses.filter(c=>plan.tracking?.[c.id]?.status==='completed'||plan.profile.priorCodes.includes(c.code)):[],doneCredits=creditsOf(done),totalCredits=plan?creditsOf(plan.courses):0;
 const rail=`<nav class="dashboard-tabs" aria-label="Your planning space">${tabs.map(([id,title,icon])=>`<button type="button" data-action="dashboard-panel" data-panel="${id}" class="${panel===id?'active':''}" ${panel===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${title}${ready[id]?'<i aria-label="Ready">✓</i>':''}</button>`).join('')}</nav>`;
 const heading=`<header class="dashboard-heading"><div><span class="dashboard-kicker">YOUR AUI PATH</span><h1>${panel==='overview'?(name?`${esc(name)}’s next chapter`:'Your next chapter'):esc(tabs.find(t=>t[0]===panel)?.[1]||'Your space')}</h1><button type="button" class="degree-chip" data-action="dashboard-direction-options" aria-label="Change your degree">${esc(profile.program)} <span aria-hidden="true">✎</span></button></div><div class="dashboard-actions">${plan?button(draft?'dashboard-save':'dashboard-change',draft?'Save this plan':'Ask for a change',true):button('dashboard-build','Build my roadmap →',true)}<button class="text-button" data-action="my-plans">My plans</button></div></header>`;
 let body='';
 if(panel==='direction')body=directionCard(profile,j,plan,true);
 else if(panel==='courses')body=courseDeck(profile,j,plan,runtime);
 else if(panel==='opportunities')body=opportunityDeck(j,plan,runtime);
 else if(panel==='semesters')body=semesterDeck(profile,j,plan,runtime);
 else body=`<section class="path-hero"><div><span class="dashboard-kicker">${plan&&!draft?'YOUR DEGREE':'A DIRECTION TO EXPLORE'}</span><h2>${esc(degree.name.replace(/^Bachelor of (Science|Arts) in /,'').replace(/^Bachelor of /,''))}</h2><p>${esc([degree.tracks.find(t=>t.id===profile.track)?.name,selectedMinor(profile)?.name?selectedMinor(profile).name+' minor':null].filter(Boolean).join(' + '))}</p><button class="text-button" data-action="dashboard-panel" data-panel="direction">Make it yours ↗</button></div><div class="path-orbit" aria-hidden="true"><span>YOU</span><b>✦</b></div></section>${plan&&!draft?`<div class="degree-progress"><div><span>${doneCredits} / ${totalCredits} credits completed</span><button type="button" class="text-button" data-action="dashboard-panel" data-panel="semesters">Update progress ↗</button></div><progress value="${doneCredits}" max="${totalCredits||1}" aria-label="Degree credits completed"></progress></div>`:`<div class="dashboard-progress" aria-label="${completed} of 4 parts ready"><span>Your plan is taking shape</span><div>${Object.values(ready).map(x=>`<i class="${x?'ready':''}"></i>`).join('')}</div></div>`}<section class="path-grid">${tile('courses','Your courses',ready.courses?`${coursesFor(profile).filter(c=>c.choice&&c.code).length} personal choices`:'Turn your interests into skills',ready.courses?'Explore courses':'Choose my courses','▤')}${tile('opportunities','Beyond the classroom',ready.opportunities?`${(plan?.targets?.internships||j.details?.internships||[]).length} companies · ${(plan?.targets?.exchanges||j.details?.exchanges||[]).length} exchange ideas`:'Find your people and places',ready.opportunities?'Explore matches':'Find my opportunities','◎')}${tile('semesters','See your future',plan?`${plan.terms.filter(t=>!['prior','pending'].includes(t.id)).length} semesters mapped`:'A clear path from here to graduation',plan?'Open my semesters':'Map my semesters','▦')}</section>${plan?`<div class="dashboard-footnote"><span>${draft?'Preview · save when it feels right':'Saved to your account'}</span>${button('dashboard-export','Export Excel')}${button('mistake-report','Report a mistake')}</div>`:''}`;
 return `<section class="student-dashboard">${heading}${rail}${working(runtime)}${failure(runtime)}${plan?.revisionAssessment?.delayed?`<p class="dashboard-error" role="status">This change moves graduation from ${esc(plan.revisionAssessment.before)} to ${esc(plan.revisionAssessment.after)}.</p>`:''}${plan?.revisionAssessment?.unmatchedRecords?`<p class="dashboard-notice">${plan.revisionAssessment.unmatchedRecords} past course${plan.revisionAssessment.unmatchedRecords===1?' needs':'s need'} adviser review for credit in this degree. Your study record is kept.</p>`:''}<div class="dashboard-content">${body}</div>${runtime.dashboardNotice?`<p class="dashboard-notice" role="status">${esc(short(runtime.dashboardNotice,170))}</p>`:''}<form id="dashboard-command-form" class="dashboard-command"><label for="dashboard-request">Make it more you</label><div><input id="dashboard-request" name="request" maxlength="2500" required minlength="5" placeholder="More startups? A different minor? Lighter semesters?" ${runtime.busy?'disabled':''}><button type="submit" class="button primary" ${runtime.busy?'disabled':''}>Ask GoPlan <span aria-hidden="true">↗</span></button></div></form></section>`;
}
function tile(panel,title,subtitle,cta,icon){return `<article class="path-tile"><span class="path-tile-icon" aria-hidden="true">${icon}</span><h2>${title}</h2><p>${esc(subtitle)}</p>${button('dashboard-open',cta,false,`data-panel="${panel}"`)}</article>`;}
function working(runtime){return runtime.busy?`<div class="dashboard-working" role="status"><span class="working-spinner" aria-hidden="true"></span><div><strong>${esc(runtime.dashboardWork||'Shaping your path…')}</strong><small>You can stay right here.</small></div></div>`:'';}
function failure(runtime){return runtime.aiError?`<div class="dashboard-error" role="alert"><p>${esc(short(runtime.aiError,180))}</p>${runtime.aiFailure?.retryable===false?button('dashboard-change','Try a different request'):button('dashboard-retry','Try again')}</div>`:'';}
function directionCard(profile,j,plan,full=false){
 const degree=programFor(profile),a=plan?.decisions?.advice?.academic||j.advice?.academic||{},minor=selectedMinor(profile),items=[['Degree',degree.name,a.rationale],['Focus',degree.tracks.find(t=>t.id===profile.track)?.name||'A broad foundation',a.focusRationale],...(profile.secondTrack?[['Second focus',degree.tracks.find(t=>t.id===profile.secondTrack)?.name,a.secondFocusRationale]]:[]),...(minor?[['Minor',minor.name,a.minorRationale]]:[])];
 return `<section class="decision-deck">${items.map(([kind,name,reason])=>`<article class="decision-card"><span class="dashboard-kicker">${kind}</span><h2>${esc(name)}</h2><p>${esc(short(reason,130))}</p>${reason?`<button class="text-button" data-action="dashboard-why" data-kind="${kind}">Why this match? ↗</button>`:''}</article>`).join('')}</section><div class="deck-actions">${button('dashboard-change','Try a different combination')}${button('dashboard-direction-options','Choose the details myself')}</div>`;
}
function courseDeck(profile,j,plan,runtime){
 if(!dashboardReady(j,plan).courses)return emptyDeck('Skills for your next chapter','Let GoPlan pick courses that fit your direction.','dashboard-courses','Choose my courses →');
 const all=plan?.courses||coursesFor(profile),minor=minorSummary(profile),group=runtime.courseGroup||'personal',visible=all.filter(c=>group==='all'||group==='minor'?group==='all'||!!c.minorId:c.choice||!!c.minorId),groups=[['personal','Your choices'],...(minor?[['minor','Your minor']]:[]),['all','All degree courses']];
 return `<div class="deck-heading"><div><h2>${group==='minor'?esc(minor?.name||'Your minor'):'Courses that fit your path'}</h2>${minor?`<p>${minor.requiredCourses} minor courses · ${minor.requiredCredits} credits${minor.approvalRequired?' · adviser confirmation':''}</p>`:''}</div>${button('dashboard-change','Swap something')}</div><div class="deck-filters" role="group" aria-label="Course group">${groups.map(([id,title])=>`<button class="${group===id?'active':''}" data-action="dashboard-course-group" data-group="${id}">${title}</button>`).join('')}</div><div class="course-deck">${visible.map(c=>`<button type="button" class="course-flashcard" data-action="dashboard-course" data-course-id="${esc(c.id)}"><span class="course-flash-type">${esc(courseStatus(plan,c)|| (c.minorId?'Minor':c.supportingPrerequisite?'Preparation':c.choice?'Your choice':'Degree core'))}</span><h3>${esc(c.title)}</h3><span>${esc(c.code||'Choose with your adviser')} <b>${c.credits} cr</b></span></button>`).join('')}</div>`;
}
function opportunityDeck(j,plan,runtime){
 if(!dashboardReady(j,plan).opportunities)return emptyDeck('Find your next horizon','Companies and exchange destinations, matched to your interests.','dashboard-targets','Find my matches →');
 const type=runtime.targetGroup||'internships',targets=plan?.targets||j.details||{},items=targets[type]||[];
 return `<div class="deck-heading"><div><h2>Your next horizons</h2><p>Targets to explore. Openings and eligibility still need checking.</p></div>${button('dashboard-change','Different matches')}</div><div class="deck-filters" role="group" aria-label="Opportunity type">${[['internships','Moroccan companies'],['exchanges','Exchange destinations']].map(([id,title])=>`<button class="${type===id?'active':''}" data-action="dashboard-target-group" data-group="${id}">${title}</button>`).join('')}</div><div class="opportunity-deck">${items.map((t,i)=>`<article class="opportunity-flashcard"><span class="opportunity-number">${String(i+1).padStart(2,'0')}</span><span class="dashboard-kicker">${esc(type==='exchanges'?t.country||'Exchange':t.organizationType==='startup'?'Startup':'Morocco')}</span><h3>${esc(t.name)}</h3><p>${esc(short(t.reason,125))}</p><button class="text-button" data-action="dashboard-target" data-target-type="${type}" data-target-index="${i}">Explore this match ↗</button></article>`).join('')||'<p>No suitable match yet. Ask GoPlan to explore another focus.</p>'}</div>`;
}
function semesterDeck(profile,j,plan,runtime){
 if(!plan)return emptyDeck('Your future, one semester at a time','We’ll connect your choices into a course sequence.','dashboard-build','Map my semesters →');
 const terms=plan.terms.filter(t=>t.id!=='prior'),selected=terms.find(t=>t.id===runtime.selectedTerm)||terms.find(t=>t.id!=='pending'&&t.courses.some(id=>plan.tracking?.[id]?.status==='in-progress'))||terms.find(t=>t.id!=='pending'&&t.courses.some(id=>plan.tracking?.[id]?.status!=='completed'))||terms[0],issues=planIssues(plan),review=plan.revisionAssessment;
 return `<div class="deck-heading"><div><h2>Your semester map</h2><p>${profile.regularCourses} courses per regular term${profile.summers?` · ${profile.summerCourses} per summer`:' · summers free'}</p></div>${button('dashboard-pace','Change my pace')}</div><div class="semester-pills" aria-label="Choose a semester">${terms.map(t=>`<button class="${selected?.id===t.id?'active':''}" data-action="dashboard-term" data-term="${esc(t.id)}">${esc(label(t))}</button>`).join('')}</div><div class="semester-focus"><div class="deck-heading"><h3>${esc(selected?label(selected):'Your courses')}</h3><span>${creditsOf((selected?.courses||[]).map(id=>plan.courses.find(c=>c.id===id)))} credits</span></div><div class="course-deck">${(selected?.courses||[]).map(id=>{const c=plan.courses.find(c=>c.id===id);return `<button type="button" class="course-flashcard" data-action="dashboard-course" data-course-id="${esc(id)}"><span class="course-flash-type">${esc(courseStatus(plan,c)||(c.minorId?'Minor':c.choice?'Your choice':'Degree core'))}</span><h3>${esc(c.title)}</h3><span>${esc(c.code||'To confirm')} <b>${c.credits} cr</b></span></button>`;}).join('')||'<p>Space for your next chapter.</p>'}</div></div><div class="deck-actions">${button('dashboard-unavailable','A course isn’t offered')}${issues.length?button('checks',`${issues.length} adviser checks`):'<span class="dashboard-check">✓ No scheduling conflicts found</span>'}</div>`;
}
function emptyDeck(title,copy,action,cta){return `<section class="empty-deck"><span aria-hidden="true">✦</span><h2>${title}</h2><p>${copy}</p>${button(action,cta,true)}</section>`;}

function courseStatus(plan,c){const status=plan?.tracking?.[c.id]?.status;return status==='completed'||plan?.profile?.priorCodes?.includes(c.code)?'✓ Completed':status==='in-progress'?'● Taking now':status==='retake'?'Retake':'';}
